/**
 * bundle.js — combines every src/*.gs file into dist/Code.gs so the whole
 * backend can be pasted into the Apps Script editor as ONE file.
 * Order follows dependencies (Config first, Router/Main last).
 *   node scripts/bundle.js
 */
'use strict';
const fs = require('fs');
const path = require('path');
const SRC = path.join(__dirname, '..', 'src');
const ORDER = ['Config', 'Utils', 'Database', 'Security', 'Session', 'Auth', 'AuditService', 'Validation',
  'EmployeeService', 'MealService', 'MenuService', 'OrderService', 'KitchenService', 'ReportService',
  'LineService', 'NotificationService', 'BackupService', 'TriggerService', 'AdminService', 'Router', 'Main'];
const all = fs.readdirSync(SRC).filter((f) => f.endsWith('.gs')).map((f) => f.replace(/\.gs$/, ''));
const missing = all.filter((f) => !ORDER.includes(f));
if (missing.length) throw new Error('Add to ORDER: ' + missing.join(', '));
const version = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8')).version;
let out = '/**\n * Factory Food Ordering System v' + version + ' — ALL backend code in one file.\n' +
  ' * GENERATED by scripts/bundle.js from src/*.gs — do not edit here; edit src/ and re-run `npm run bundle`.\n' +
  ' * Paste this file as "Code.gs" (delete all other .gs files first), plus the 8 .html files and appsscript.json.\n */\n';
ORDER.forEach((name) => {
  out += '\n\n/* ======================================================================= */\n/* ' + name + '.gs */\n/* ======================================================================= */\n\n';
  out += fs.readFileSync(path.join(SRC, name + '.gs'), 'utf8');
});
fs.mkdirSync(path.join(__dirname, '..', 'dist'), { recursive: true });
fs.writeFileSync(path.join(__dirname, '..', 'dist', 'Code.gs'), out);
console.log('dist/Code.gs written (' + out.split('\n').length + ' lines, ' + ORDER.length + ' files)');
